<script>
document.addEventListener('DOMContentLoaded', function () {
	const canteenBreakLimit = document.querySelector('[name="canteen_break_limit"]');
	if (canteenBreakLimit) {
		canteenBreakLimit.type = 'text';
		canteenBreakLimit.inputMode = 'numeric';
		canteenBreakLimit.maxLength = 5;
		canteenBreakLimit.placeholder = 'HH:MM';
		canteenBreakLimit.oninput = function (event) {
			this.value = this.value.replace(/\D/g, '').slice(0, 4).replace(/^(\d{2})(?=\d)/, '$1:');
			if (this.value.length === 2 && event.inputType !== 'deleteContentBackward') this.value += ':';
		};
	}
	const eligibleForCoff = document.getElementById('is_eligible_for_c_off');
	const cOffSettingsCard = document.querySelector('.c-off-settings-card');
	const allowBackdatedLeave = document.getElementById('allow_backdated_leave');
	const backdatedDayLimitField = document.querySelector('.backdated-day-limit-field');
	const fixWorkHours = document.getElementById('fix_work_hours');
	const fixWorkHoursAsPerShift = document.getElementById('fix_work_hours_as_per_shift');
	const asPerShiftField = document.querySelector('.fix-work-hours-as-per-shift-field');
	const valueField = document.querySelector('.fix-work-hours-value-field');

	function updateFixWorkHoursFields() {
		const useFixWorkHours = fixWorkHours?.checked;
		const useShiftHours = fixWorkHoursAsPerShift?.checked;
		if (asPerShiftField) asPerShiftField.classList.toggle('d-none', !useFixWorkHours);
		if (valueField) valueField.classList.toggle('d-none', !useFixWorkHours || useShiftHours);
	}

	function updateCoffFields() {
		if (cOffSettingsCard) cOffSettingsCard.classList.toggle('d-none', !eligibleForCoff?.checked);
		if (backdatedDayLimitField) backdatedDayLimitField.classList.toggle('d-none', !allowBackdatedLeave?.checked);
	}

	eligibleForCoff?.addEventListener('change', updateCoffFields);
	allowBackdatedLeave?.addEventListener('change', updateCoffFields);
	fixWorkHours?.addEventListener('change', updateFixWorkHoursFields);
	fixWorkHoursAsPerShift?.addEventListener('change', updateFixWorkHoursFields);
	updateCoffFields();
	updateFixWorkHoursFields();
});
</script>
